with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'modern-test-automation-bootcamp' and mo.module_number = 7),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A "page object" on your team is a class whose only members are getters that return locators, like `get emailInput() { return this.page.getByLabel('Email'); }`, and every spec still calls `.fill()` and `.click()` itself. What is the strongest criticism of this design?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$It is getter-soup: it renames selectors but moves no behaviour, so the flow logic and its duplication still live in the specs and a workflow change still touches many files$qz$, true), ($qz$Returning locators from getters is a Playwright anti-pattern because locators must be created inside the test function to auto-wait correctly$qz$, false), ($qz$Page objects must not expose locators at all; the fix is to make every getter private and unreachable from the spec$qz$, false), ($qz$The design is sound and complete; centralising selectors in getters is the entire purpose of the Page Object Model$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A team automating a five-spec smoke test proposes building a base page class, a component library and a fixture layer before writing any tests. Why is this a poor decision?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$It pays the cost of structure before they have the pain it solves; abstraction is overhead until duplication and shotgun edits justify it, and five specs rarely do$qz$, true), ($qz$A base page class is always wrong in Playwright because composition is the only supported pattern$qz$, false), ($qz$Smoke tests specifically are exempt from any structure and must always be single-file scripts by convention$qz$, false), ($qz$The plan is correct; more architecture up front always reduces maintenance later regardless of suite size$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What does this custom fixture provide to a test that requests `loggedInPage`?

~~~ts
export const test = base.extend<{ loggedInPage: Page }>({
  loggedInPage: async ({ browser }, use) => {
    const context = await browser.newContext({ storageState: 'auth/user.json' });
    const page = await context.newPage();
    await use(page);
    await context.close();
  },
});
~~~$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$A page in a fresh context pre-seeded with saved authentication state, set up before the test body and torn down after via the code following `use`$qz$, true), ($qz$A page that logs in through the UI on every test by replaying the steps stored in the JSON file$qz$, false), ($qz$A single shared page reused across every test in the file, so state from one test carries into the next$qz$, false), ($qz$A page object instance; `loggedInPage` is Playwright syntax for generating a POM automatically$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$When does introducing a Page Object Model genuinely pay off, rather than adding indirection for its own sake?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$When a UI area is driven by many specs so that centralising its interactions gives one place to change when the UI shifts$qz$, true), ($qz$Always, on the first spec, because every professional Playwright suite is required to use POM$qz$, false), ($qz$Only for pages with more than a fixed number of form fields, below which POM is forbidden$qz$, false), ($qz$Never in Playwright, because locators and fixtures make the Page Object Model obsolete in every case$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A `LoginPage` class exposes a method `async login(email, password)` that fills the form and clicks submit, but it also contains `expect(this.page).toHaveURL('/dashboard')` inside that method. Why do many teams consider putting the assertion there a mistake?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$It bakes one expected outcome into the reusable action, so the page object cannot be used to test a failed login without lying about what "login" means$qz$, true), ($qz$Assertions are not allowed to run inside async methods and will be silently skipped$qz$, false), ($qz$Page objects are forbidden from importing `expect`, so the file will not compile$qz$, false), ($qz$The assertion makes the method slower, which is the only real objection$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Your suite has grown to hundreds of specs and you want to run only the fast, critical checks on every pull request. Which approach best supports this without duplicating specs?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Tag specs (for example `@smoke`, `@slow`) and select them at run time with a grep/tag filter, keeping one copy of each test$qz$, true), ($qz$Copy the critical specs into a separate folder and maintain both copies by hand$qz$, false), ($qz$Comment out the slow specs before each pull-request run and uncomment them afterwards$qz$, false), ($qz$Delete the slow specs, since anything not run on every pull request has no value$qz$, false)) as v(t, c) returning question_id),
q7 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A reviewer says a helper called `createOrder()` that navigates the UI, fills a checkout form and asserts a confirmation banner is "doing too much". In framework terms, what is the underlying concern?$qz$, 'multiple_choice', 7 from newq returning id),
a7 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q7.id, v.t, v.c from q7, (values ($qz$It mixes navigation, interaction and assertion into one opaque unit, so it cannot be reused as a setup step without also forcing its assertion and it is hard to reason about failures$qz$, true), ($qz$Helper functions are not permitted to call more than one Playwright API method$qz$, false), ($qz$The concern is purely naming; renaming it to `checkout()` resolves the design problem entirely$qz$, false), ($qz$Nothing is wrong; a single all-in-one helper per feature is the recommended structure at any scale$qz$, false)) as v(t, c) returning question_id),
q8 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which situation is the clearest sign that a suite has outgrown its lack of structure and now needs some?$qz$, 'multiple_choice', 8 from newq returning id),
a8 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q8.id, v.t, v.c from q8, (values ($qz$Adding a "remember me" checkbox to the login form requires editing dozens of specs because each drives the login form directly$qz$, true), ($qz$A single new engineer asks where a test file lives on their first day$qz$, false), ($qz$The suite contains more than a round number of spec files, regardless of duplication$qz$, false), ($qz$One spec occasionally takes slightly longer than the others to run$qz$, false)) as v(t, c) returning question_id),
q9 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What is the practical difference between using fixtures for dependency injection versus calling helper functions at the top of each test?$qz$, 'multiple_choice', 9 from newq returning id),
a9 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q9.id, v.t, v.c from q9, (values ($qz$Fixtures declare a test’s needs by parameter and guarantee setup and teardown around the test, whereas a manually-called helper leaves teardown and ordering to the author to remember$qz$, true), ($qz$There is no difference; fixtures are only syntactic sugar over calling a helper and behave identically on failure$qz$, false), ($qz$Helper functions run in parallel automatically while fixtures always force serial execution$qz$, false), ($qz$Fixtures can only provide primitive values, so any object such as a page must come from a helper$qz$, false)) as v(t, c) returning question_id),
q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A team decides every spec must extend a deep inheritance chain: `BasePage` → `AuthenticatedPage` → `DashboardPage` → `ReportsPage`. Six months on, changes to `BasePage` break unrelated pages. What does this illustrate?$qz$, 'multiple_choice', 10 from newq returning id),
a10 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q10.id, v.t, v.c from q10, (values ($qz$Deep inheritance couples unrelated pages through a shared base, so a change high in the chain ripples widely; composition of small components is usually the more flexible choice$qz$, true), ($qz$Inheritance is never usable in test frameworks and the language should forbid it$qz$, false), ($qz$The chain is simply one level too short; adding another base class would have prevented the breakage$qz$, false), ($qz$The breakage proves the pages were not tagged correctly, which is the real root cause$qz$, false)) as v(t, c) returning question_id),
q11 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You are asked to justify a proposed component object for a reusable date-picker that appears on eight different pages. Which justification is soundest?$qz$, 'multiple_choice', 11 from newq returning id),
a11 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q11.id, v.t, v.c from q11, (values ($qz$The widget is duplicated across many pages, so a component object gives one place to change its interactions and stops eight copies drifting apart$qz$, true), ($qz$Every widget should have a component object regardless of how many places it appears, for consistency$qz$, false), ($qz$A date-picker is complex, and complex widgets must always be abstracted even if they appear only once$qz$, false), ($qz$Component objects make tests run faster, which is the primary reason to introduce one$qz$, false)) as v(t, c) returning question_id)
