q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Why do many teams prefer a programmatic or API-based login for their setup step over driving the login form in the browser?$qz$, 'multiple_choice', 2 from newq returning id),
