a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Define per-role Playwright projects, each with its own storageState file, and route each spec to the project whose role it needs$qz$, true), ($qz$Log in as admin once and downgrade the role inside each standard-user test at run time$qz$, false), ($qz$Store both roles in a single storageState file and hope the correct one is used per test$qz$, false), ($qz$Share one session and switch roles by editing cookies mid-test from within each spec$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A test passes in isolation but fails when the whole file runs, and the failure changes depending on which test ran before it. What is the most likely cause?$qz$, 'multiple_choice', 4 from newq returning id),
