with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'modern-test-automation-bootcamp' and mo.module_number = 12),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What does this workflow fragment cause to happen?

~~~yaml
on:
  pull_request:
    branches: [main]
jobs:
  e2e:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm ci
      - run: npx playwright install --with-deps
      - run: npx playwright test
~~~$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$On every pull request targeting `main`, it checks out the code, installs dependencies and browsers, then runs the Playwright suite on an Ubuntu runner$qz$, true), ($qz$It runs the Playwright suite once per day on a schedule against the `main` branch$qz$, false), ($qz$It runs only when someone pushes directly to `main`, not on pull requests$qz$, false), ($qz$It deploys the application to production after the tests pass$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Why is `npx playwright install --with-deps` typically required in CI but not on a developer’s machine?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$A fresh CI runner has no browsers or their system libraries, so they must be installed each run, whereas a developer machine usually already has them$qz$, true), ($qz$The flag upgrades Playwright to the latest version, which developers do manually$qz$, false), ($qz$CI cannot run `npm ci`, so browser installation replaces it$qz$, false), ($qz$It is only needed to enable video recording, which developers rarely use$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What is the effect of this caching step, and its main limitation?

~~~yaml
- uses: actions/cache@v4
  with:
    path: ~/.npm
    key: npm-${{ hashFiles('package-lock.json') }}
~~~$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$It restores the npm download cache when the lockfile is unchanged, speeding up `npm ci`; it does not cache the Playwright browser binaries, which live elsewhere$qz$, true), ($qz$It caches the Playwright browsers, so the install step can be removed entirely$qz$, false), ($qz$It caches the test results so unchanged tests are skipped on the next run$qz$, false), ($qz$It disables installation completely whenever the cache key matches$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A team wants a failing Playwright suite to block a pull request from merging. Beyond adding the workflow, what else is required?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$A branch protection rule that marks the test job a required status check, so the merge is blocked until it passes$qz$, true), ($qz$Nothing else; any failing workflow automatically prevents merging by default$qz$, false), ($qz$A manual reviewer must re-run the tests locally and confirm before each merge$qz$, false), ($qz$The workflow must be renamed to `required.yml` for GitHub to enforce it$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What does this matrix configuration do?

~~~yaml
strategy:
  matrix:
    shard: [1, 2, 3, 4]
steps:
  - run: npx playwright test --shard=${{ matrix.shard }}/4
~~~$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$It splits the suite into four shards run as four parallel jobs, each executing a quarter of the tests, to cut wall-clock time$qz$, true), ($qz$It runs the entire suite four times over to detect flaky tests through repetition$qz$, false), ($qz$It runs the suite on four different browsers, one per shard number$qz$, false), ($qz$It retries the suite up to four times if the first run fails$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$After sharding a suite across four parallel jobs, how do you obtain a single combined test report?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Have each shard upload its blob report as an artifact, then a final job downloads them all and merges them into one report$qz$, true), ($qz$The last shard to finish automatically overwrites the others with a complete report$qz$, false), ($qz$Sharded runs cannot be reported together; you must read four separate reports$qz$, false), ($qz$Set a flag so shard 1 alone produces the full report for the whole suite$qz$, false)) as v(t, c) returning question_id),
q7 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A CI run is green, but a developer notices the Playwright step actually exited before running because a prior step failed silently and `continue-on-error: true` was set on the test step. What is the real problem?$qz$, 'multiple_choice', 7 from newq returning id),
a7 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q7.id, v.t, v.c from q7, (values ($qz$The quality gate is not enforcing anything: `continue-on-error` lets the job report success regardless of the test outcome, so a green tick no longer means the tests passed$qz$, true), ($qz$Nothing is wrong; `continue-on-error` is the correct way to make flaky suites reliable$qz$, false), ($qz$The tests genuinely passed; a green run is definitive proof by itself$qz$, false), ($qz$The problem is only cosmetic reporting and does not affect whether merges are blocked$qz$, false)) as v(t, c) returning question_id),
q8 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Why is running the browsers in headless mode the sensible default in CI, whereas a developer often wants headed mode locally?$qz$, 'multiple_choice', 8 from newq returning id),
a8 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q8.id, v.t, v.c from q8, (values ($qz$CI runners have no display and headless is faster, while a developer benefits from watching the browser when debugging a failure$qz$, true), ($qz$Headless mode runs a different, more lenient set of assertions suited to servers$qz$, false), ($qz$Headed mode is impossible in CI because Playwright forbids it entirely$qz$, false), ($qz$Headless tests and headed tests exercise different code paths in the product, so CI needs headless for coverage$qz$, false)) as v(t, c) returning question_id),
q9 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A workflow always uploads the HTML report and traces only when tests fail, using `if: failure()` on the upload step. Why is this a good pattern?$qz$, 'multiple_choice', 9 from newq returning id),
a9 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q9.id, v.t, v.c from q9, (values ($qz$It preserves the diagnostic artefacts needed to debug a CI-only failure, while avoiding uploading large reports for every green run$qz$, true), ($qz$It makes failing tests pass by attaching a report to them$qz$, false), ($qz$It is required syntax; Playwright reports cannot be uploaded on success$qz$, false), ($qz$It retries the failed tests using the uploaded trace as input$qz$, false)) as v(t, c) returning question_id),
q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A pull-request suite takes far too long, so a team pins the CI to a single worker to "make it stable". Runs are stable but even slower. What is the better trade-off to investigate first?$qz$, 'multiple_choice', 10 from newq returning id),
a10 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q10.id, v.t, v.c from q10, (values ($qz$Keep parallelism and instead fix the tests’ shared-state coupling and shard the run, so speed is retained without the flakiness that parallelism exposed$qz$, true), ($qz$A single worker is the correct permanent setting; parallel testing is inherently unreliable$qz$, false), ($qz$Reduce the number of tests until the suite is fast, since slow suites have no value$qz$, false), ($qz$Increase the default timeout so slow serial runs stop failing, accepting the longer time$qz$, false)) as v(t, c) returning question_id),
q11 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What does `runs-on` combined with a `matrix.browser: [chromium, firefox, webkit]` express in a workflow?$qz$, 'multiple_choice', 11 from newq returning id),
a11 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q11.id, v.t, v.c from q11, (values ($qz$The job fans out into parallel runs, one per listed browser, so the suite is exercised across all three engines$qz$, true), ($qz$It selects a single browser at random from the three for each run$qz$, false), ($qz$It installs all three browsers but runs the tests only on the first that succeeds$qz$, false), ($qz$It merges the three browsers into one combined engine for the run$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'modern-test-automation-bootcamp' and mo.module_number = 14),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An assistant generates this test for a login page. What is the most serious problem a reviewer should catch?

~~~ts
test('login works', async ({ page }) => {
  await page.goto('/login');
  await page.fillForm({ email: 'a@b.com', password: 'pw' });
  await page.clickButton('Sign in');
  await expect(page).toBeTruthy();
});
~~~$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$It uses hallucinated APIs (`page.fillForm`, `page.clickButton` do not exist) and a meaningless assertion (`expect(page).toBeTruthy()` is always true), so it would not even represent a real, passing test of login$qz$, true), ($qz$The email address is not a real inbox, so the test cannot authenticate$qz$, false), ($qz$The only issue is the missing `await` on the final expect$qz$, false), ($qz$It is fine as written; these are standard Playwright convenience methods$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An AI-written test passes reliably. On review you find its single assertion is `await expect(page.locator('body')).toBeVisible()` after submitting a payment form. Why should this test not be trusted?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$The assertion is true for essentially any page that loads, so the test would stay green even if the payment silently failed — it verifies nothing about the behaviour under test$qz$, true), ($qz$Asserting on the body element is slower than asserting on a specific locator$qz$, false), ($qz$The test is trustworthy precisely because it passes reliably; reliability is the goal$qz$, false), ($qz$The problem is only that `body` should be selected with a data-testid instead$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An assistant confidently suggests calling `await page.waitForNetworkIdle()` to fix a flaky test. You cannot find that method in the Playwright API. What is the right conclusion?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$It is likely a hallucinated API; verify against the real documentation and use a supported wait such as awaiting a specific response or a web-first assertion instead$qz$, true), ($qz$The method exists but is hidden; call it anyway since the assistant is usually right$qz$, false), ($qz$Any method an assistant suggests must exist, so the local Playwright install is simply out of date$qz$, false), ($qz$Flakiness cannot be fixed without that method, so the test should be deleted$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An assistant offers to speed up your setup by embedding a working admin API key directly in the committed test file. What is the correct response?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Refuse: secrets must not be committed; inject the key from an environment variable or secret store, and rotate the exposed key if it was ever shared$qz$, true), ($qz$Accept it for now, since a key in a private repository is not really exposed$qz$, false), ($qz$Accept it but add a code comment asking colleagues not to look at the key$qz$, false), ($qz$Accept it only if the key belongs to a test environment, as those keys are exempt from secret handling$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A generated test asserts `expect(response.status()).toBe(200)` for an endpoint whose specification says a successful creation returns 201. The test is green against a stub that returns 200. What has gone wrong?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$The assertion encodes the wrong expected status; it passes against the stub but would wrongly fail (or hide a defect) against the real API — green here does not mean correct$qz$, true), ($qz$Nothing; 200 and 201 are interchangeable and the test is correct$qz$, false), ($qz$The stub is faulty and the test is right; the real API should also return 200$qz$, false), ($qz$The only fix needed is to increase the request timeout$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What is the most reliable way to review an AI-generated Playwright test for correctness before trusting it?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Read what each assertion actually proves, confirm every API used exists, and check it fails when the behaviour is broken — not just that it passes today$qz$, true), ($qz$Run it once; if it is green, it is correct and needs no further scrutiny$qz$, false), ($qz$Trust it if the assistant expresses high confidence in its explanation$qz$, false), ($qz$Accept it if it compiles without type errors, since that proves the logic is sound$qz$, false)) as v(t, c) returning question_id),
q7 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An assistant produces a test with the assertion `expect(await page.title()).toContain('')`. Why is this a red flag even though it passes?$qz$, 'multiple_choice', 7 from newq returning id),
a7 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q7.id, v.t, v.c from q7, (values ($qz$Every string contains the empty string, so the assertion can never fail — it is a tautology dressed up as a check$qz$, true), ($qz$Page titles cannot be read asynchronously, so the await is misplaced$qz$, false), ($qz$It should use `toBe` rather than `toContain` for titles, which is the only issue$qz$, false), ($qz$It is a strong assertion because it confirms the page has a title element at all$qz$, false)) as v(t, c) returning question_id),
q8 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$When an AI assistant writes tests for you, who is accountable for a defect that a weak generated assertion let slip into production?$qz$, 'multiple_choice', 8 from newq returning id),
a8 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q8.id, v.t, v.c from q8, (values ($qz$The engineer who reviewed and merged the test; authorship by a tool does not transfer responsibility for what ships$qz$, true), ($qz$The assistant vendor, since their model produced the assertion$qz$, false), ($qz$Nobody, because AI-generated code carries no ownership$qz$, false), ($qz$The original test framework authors, for allowing weak assertions to compile$qz$, false)) as v(t, c) returning question_id),
q9 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A generated suite has high line coverage and all tests are green, and the assistant cites the coverage number as evidence of quality. What is the sound rebuttal?$qz$, 'multiple_choice', 9 from newq returning id),
a9 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q9.id, v.t, v.c from q9, (values ($qz$Coverage measures which code ran, not whether the assertions would catch a defect; tests can execute every line while asserting nothing meaningful$qz$, true), ($qz$High coverage does guarantee quality, so the assistant is correct and no rebuttal is needed$qz$, false), ($qz$Coverage is irrelevant because only the number of tests matters$qz$, false), ($qz$The coverage figure must be wrong, since green suites cannot have measurable coverage$qz$, false)) as v(t, c) returning question_id),
q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An assistant proposes pasting a failing production log containing real customer records into a public model prompt to help debug a test. How should you judge this?$qz$, 'multiple_choice', 10 from newq returning id),
a10 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q10.id, v.t, v.c from q10, (values ($qz$Reject it: sending real customer data to an external service risks a privacy and security breach; redact or synthesise the data before sharing any excerpt$qz$, true), ($qz$Allow it, since debugging is a legitimate purpose that overrides data-handling rules$qz$, false), ($qz$Allow it if the prompt is deleted afterwards, which removes any exposure$qz$, false), ($qz$Allow it because logs are technical artefacts and never count as personal data$qz$, false)) as v(t, c) returning question_id),
q11 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An assistant generates a test that uses `page.getByRole('button', { name: 'Submit' })` and asserts `await expect(page.getByText('Thank you')).toBeVisible()` after a real form submission. How should a reviewer treat this one?$qz$, 'multiple_choice', 11 from newq returning id),
a11 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q11.id, v.t, v.c from q11, (values ($qz$It uses real APIs and a meaningful, behaviour-specific assertion, so it is a reasonable starting point — still verify the locator matches the app and that it fails when submission breaks$qz$, true), ($qz$Reject it outright, because any AI-generated test is untrustworthy regardless of content$qz$, false), ($qz$Accept it without review, because it uses role-based locators which are always correct$qz$, false), ($qz$Reject it because visible-text assertions are inherently weak and prove nothing$qz$, false)) as v(t, c) returning question_id)
